-- Correct the bounds table in place, once per table.
local bounds = TrailerCargo.Bounds
if bounds and TrailerCargo.BoundsUnitsApplied ~= bounds then
  TrailerCargo.BoundsUnitsApplied = bounds
  for key, row in pairs(bounds) do
    local bare = string.sub(key, 1, 2) == "W:" and string.sub(key, 3) or key
    local k = TrailerCargo.Units[bare]
    if k then
      row[1], row[2], row[3] = row[1] * k, row[2] * k, row[3] * k
      row[4], row[5], row[6] = row[4] * k, row[5] * k, row[6] * k
    end
  end
  for key, row in pairs(TrailerCargo.BoundsExtra) do
    if bounds[key] == nil then bounds[key] = row end
  end
end
